import errno
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat
import sys

FOLLOWUP = "result-coordinate-evidence/materializer-followup"
PROTOCOL = FOLLOWUP + "/optimization-comparison-protocol.json"
BUNDLE_MANIFEST = FOLLOWUP + "/comparison-runtime-manifest.json"
RUNTIME_NAMES = ("original", "candidate1", "candidate1-and-2")
ORIGINAL_PROFILES = (FOLLOWUP + "/frozen-off/profile.jfr", FOLLOWUP + "/frozen-dense/profile.jfr")
PROFILES = (FOLLOWUP + "/delivery-profiles/frozen-off/profile.jfr",
            FOLLOWUP + "/delivery-profiles/frozen-dense/profile.jfr")
DISCLOSURE_RECEIPT = FOLLOWUP + "/delivery-profiles/disclosure-verification.json"
ORIGINAL_SOURCE = "15fe7d5011+worktree-sha256-34767935d60f32ba61adfb44495c607e17ca760d5d2f77a17ddb2862c4f7a8ac"
ORIGINAL_SOURCE_MAP = "34767935d60f32ba61adfb44495c607e17ca760d5d2f77a17ddb2862c4f7a8ac"
ORIGINAL_PRODUCTION = "f822ad378729e2ebdd5c7e91d2420e9dbf1eb92aab382e76c35fba00989eab8c"
LAUNCHER_TREE = "044cf5e6cca19abbaf98ff8789ee92480fd25c04f05483be257d3e18807e867a"
TEXT_SUFFIXES = {".json", ".jsonl", ".log", ".xml", ".csv", ".md", ".py", ".txt", ".out", ".err",
                 ".patch", ".diff", ".sh", ".java", ".properties", ".yaml", ".yml", ".toml", ".jfc"}
EXCLUDED_DIRECTORIES = {"store", "stores", "target", "classes", "artifacts", "analysis-classes",
                        ".git", ".m2_repo", "__pycache__", "credentials"}


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def json_bytes(value: object) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True) + "\n").encode("utf-8")


def sha_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def file_hash(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def signature(path: Path) -> tuple[int, ...]:
    info = path.lstat()
    return (info.st_dev, info.st_ino, info.st_mode, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def portable(value: str) -> str:
    path = PurePosixPath(value)
    require(value and not path.is_absolute() and path.as_posix() == value
            and all(part not in ("", ".", "..") for part in path.parts)
            and "\\" not in value and "\0" not in value and "\n" not in value,
            f"Unsafe relative path: {value!r}")
    return value


def path_under(repo: Path, relative: str) -> Path:
    relative = portable(relative)
    path = repo
    require(stat.S_ISDIR(repo.lstat().st_mode), f"Repository must be a real directory: {repo}")
    for component in PurePosixPath(relative).parts:
        path = path / component
        require(not stat.S_ISLNK(path.lstat().st_mode), f"Symlink is not a frozen package input: {path}")
    require(path.resolve(strict=True).is_relative_to(repo), f"Path escapes repository: {path}")
    return path


def recorded_relative(value: str, original_repo: str) -> str:
    original = PurePosixPath(original_repo)
    path = PurePosixPath(value)
    require(original.is_absolute() and path.is_absolute() and path.as_posix() == value,
            f"Expected an exact recorded absolute path: {value!r}")
    return portable(path.relative_to(original).as_posix())


def member_relative(value: str) -> str:
    path = PurePosixPath(portable(value))
    require(len(path.parts) > 1 and path.parts[0] == "rdf4j", f"Unexpected archive prefix: {value}")
    return portable(PurePosixPath(*path.parts[1:]).as_posix())


def tree_digest(files: dict[str, dict]) -> str:
    digest = hashlib.sha256()
    # Match the original freezer's sorted(Path) component order, not plain string order.
    for name in sorted(files, key=PurePosixPath):
        digest.update(name.encode("utf-8") + b"\0")
        digest.update(bytes.fromhex(files[name]["sha256"]))
    return digest.hexdigest()


def real_tree(root: Path) -> list[Path]:
    require(stat.S_ISDIR(root.lstat().st_mode), f"Expected a real directory: {root}")
    files = []
    for folder, directories, filenames in os.walk(root, followlinks=False):
        base = Path(folder)
        for name in directories:
            require(stat.S_ISDIR((base / name).lstat().st_mode), f"Non-directory in tree: {base / name}")
        for name in filenames:
            path = base / name
            require(stat.S_ISREG(path.lstat().st_mode), f"Non-regular file in tree: {path}")
            files.append(path)
    return sorted(files, key=lambda path: PurePosixPath(path.relative_to(root).as_posix()))


class Inventory:
    def __init__(self, repo: Path):
        self.repo = repo
        self.files: dict[str, dict] = {}
        self.signatures: dict[str, tuple[int, ...]] = {}
        self.tree_members: dict[str, tuple[str, ...]] = {}

    def add(self, relative: str, expected: str | None = None) -> dict:
        relative = portable(relative)
        require(relative != BUNDLE_MANIFEST, "Generated bundle-manifest path is reserved")
        path = path_under(self.repo, relative)
        before = signature(path)
        require(stat.S_ISREG(before[2]), f"Expected a regular file: {path}")
        if relative in self.files:
            require(before == self.signatures[relative], f"Input changed after capture: {path}")
            record = self.files[relative]
        else:
            digest = file_hash(path)
            require(signature(path) == before, f"Input changed while hashing: {path}")
            record = {"path": "rdf4j/" + relative, "size": before[3], "sha256": digest,
                      "mode": 0o755 if before[2] & 0o111 else 0o644}
            self.files[relative] = record
            self.signatures[relative] = before
        require(expected is None or record["sha256"] == expected, f"Hash differs from frozen identity: {relative}")
        return record

    def read(self, relative: str, expected: str | None = None) -> bytes:
        record = self.add(relative, expected)
        data = path_under(self.repo, relative).read_bytes()
        require(len(data) == record["size"] and sha_bytes(data) == record["sha256"],
                f"Input changed while reading: {relative}")
        return data

    def json(self, relative: str, expected: str | None = None):
        return json.loads(self.read(relative, expected))

    def tree(self, relative: str) -> dict[str, dict]:
        root = path_under(self.repo, relative)
        members = real_tree(root)
        names = tuple(path.relative_to(root).as_posix() for path in members)
        if relative in self.tree_members:
            require(self.tree_members[relative] == names, f"Tree inventory changed: {relative}")
        else:
            self.tree_members[relative] = names
        result = {}
        for name in names:
            record = self.add(relative + "/" + name)
            result[name] = {"bytes": record["size"], "sha256": record["sha256"]}
        return result

    def assert_stable(self) -> None:
        for relative, before in self.signatures.items():
            require(signature(path_under(self.repo, relative)) == before, f"Input changed during packaging: {relative}")
        for relative, names in self.tree_members.items():
            root = path_under(self.repo, relative)
            require(tuple(path.relative_to(root).as_posix() for path in real_tree(root)) == names,
                    f"Tree membership changed during packaging: {relative}")

    def add_text_tree(self, relative: str, exclude: set[str] | None = None) -> None:
        root = path_under(self.repo, relative)
        require(stat.S_ISDIR(root.lstat().st_mode), f"Text evidence root must be a directory: {relative}")
        for folder, directories, filenames in os.walk(root, followlinks=False):
            base = Path(folder)
            retained = []
            for name in directories:
                if name in EXCLUDED_DIRECTORIES or name.endswith("-classes"):
                    continue
                require(stat.S_ISDIR((base / name).lstat().st_mode), f"Non-directory text root child: {base / name}")
                retained.append(name)
            directories[:] = retained
            for name in filenames:
                path = base / name
                if path.suffix.lower() not in TEXT_SUFFIXES:
                    continue
                rel = path.relative_to(self.repo).as_posix()
                if exclude is not None and rel in exclude:
                    continue
                data = self.read(rel)
                require(b"\0" not in data, f"Binary file disguised as text: {rel}")
                data.decode("utf-8")


def verify_experiment(repo: Path, inventory: Inventory, original_repo: str) -> dict:
    protocol_bytes = inventory.read(PROTOCOL)
    protocol = json.loads(protocol_bytes)
    require(protocol.get("status") == "frozen-ready", "Comparison protocol is not frozen")
    require(protocol["arms"] == ["original-off", "original-dense", "candidate1-dense", "candidate1-and-2-dense"]
            and (protocol["rounds"], protocol["warmup"], protocol["iterations"]) == (4, 8, 5),
            "Unexpected comparison protocol")
    inventory.add(FOLLOWUP + "/run-optimization-comparison.py", protocol["driverSha256"])
    inventory.add(FOLLOWUP + "/runtime_identity.py", protocol["identityHelperSha256"])
    original_reference = inventory.json("result-coordinate-evidence/transport-comparison/classpath-manifest.json")
    require(len(original_reference) == 126, "Original base runtime must contain 126 entries")
    runtimes = {}
    artifacts = {}
    for name in RUNTIME_NAMES:
        descriptor = protocol["runtimes"][name]
        require(isinstance(descriptor, dict), f"Missing frozen runtime: {name}")
        paths = {}
        for field, hash_field in (("classpathFile", "classpathFileSha256"),
                                  ("classpathManifestFile", "classpathManifestSha256"),
                                  ("sourceManifestFile", "sourceManifestSha256"),
                                  ("provenanceFile", "provenanceSha256"),
                                  ("originalSourceManifestFile", "originalSourceManifestSha256")):
            relative = recorded_relative(descriptor[field], original_repo)
            inventory.add(relative, descriptor[hash_field])
            paths[field] = relative
        require(paths["originalSourceManifestFile"] == "result-coordinate-evidence/final-validation/benchmark-source-hashes.json"
                and descriptor["originalSourceManifestSha256"] == ORIGINAL_SOURCE_MAP,
                "Runtime descriptor does not pin the exact measured original source map")
        manifest = inventory.json(paths["classpathManifestFile"])
        classpath = inventory.read(paths["classpathFile"]).decode("utf-8").strip()
        require(len(manifest) == 127 and classpath == ":".join(entry["path"] for entry in manifest),
                f"Classpath order/text differs from its manifest: {name}")
        if name == "original":
            require(manifest[:126] == original_reference and descriptor["sourceIdentity"] == ORIGINAL_SOURCE
                    and paths["sourceManifestFile"] == "result-coordinate-evidence/final-validation/benchmark-source-hashes.json"
                    and descriptor["sourceManifestSha256"] == ORIGINAL_SOURCE_MAP,
                    "Original arm/source map differs from preserved measured baseline")
        else:
            require(all(entry == runtimes["original"]["originalManifest"][i]
                        for i, entry in enumerate(manifest) if i != 1),
                    f"Candidate changed more than production entry 1: {name}")
            patch = recorded_relative(descriptor["productionPatchFile"], original_repo)
            inventory.add(patch, descriptor["productionPatchSha256"])
            paths["productionPatchFile"] = patch
        entries = []
        for index, entry in enumerate(manifest):
            relative = recorded_relative(entry["path"], original_repo)
            if index == 126:
                require(relative == "result-coordinate-evidence/root-qualified-launcher/classes"
                        and entry == {"path": entry["path"], "kind": "tree", "files": 1, "sha256": LAUNCHER_TREE},
                        "Last artifact is not the exact root-audit launcher")
            elif name != "original" and index == 1:
                require(relative == FOLLOWUP + "/runtimes/" + name + "/artifacts/001-classes",
                        "Candidate production classes are outside the expected frozen tree")
            else:
                require(relative.startswith("result-coordinate-evidence/frozen-current/artifacts/" + f"{index:03d}-"),
                        f"Unexpected original artifact path: {relative}")
            if relative not in artifacts:
                if entry["kind"] == "tree":
                    files = inventory.tree(relative)
                    require(len(files) == entry["files"] and tree_digest(files) == entry["sha256"],
                            f"Frozen tree differs: {relative}")
                else:
                    require(entry["kind"] == "file" and relative.endswith(".jar"),
                            f"Only recorded class trees and dependency JARs are allowed: {relative}")
                    inventory.add(relative, entry["sha256"])
                artifacts[relative] = entry | {"path": "rdf4j/" + relative, "originalAbsolutePath": entry["path"]}
            else:
                require(artifacts[relative]["sha256"] == entry["sha256"]
                        and artifacts[relative]["kind"] == entry["kind"], "Aliased artifact identity differs")
            entries.append(artifacts[relative])
        require(manifest[1]["kind"] == "tree", "Production entry must be a class/resource tree")
        if name == "original":
            require(manifest[1]["files"] == 2780 and manifest[1]["sha256"] == ORIGINAL_PRODUCTION,
                    "Original production bytes differ from the measured baseline")
        else:
            require(manifest[1]["sha256"] != ORIGINAL_PRODUCTION, "Candidate equals original production")
            snapshot_root = FOLLOWUP + "/runtimes/" + name
            inventory.add_text_tree(snapshot_root)
            recorded_files = inventory.json(snapshot_root + "/production-class-files.json")
            require(inventory.tree(snapshot_root + "/artifacts/001-classes") == recorded_files,
                    "Candidate production-file inventory differs")
            mapping = inventory.json(snapshot_root + "/archive-path-mapping.json")
            require(mapping == [{"originalAbsolutePath": entry["path"],
                                 "archiveRelativePath": entries[i]["path"], "classpathIndex": i,
                                 "sha256": entry["sha256"]} for i, entry in enumerate(manifest)],
                    "Candidate portable archive mapping differs from ordered runtime")
            source_map = inventory.json(paths["sourceManifestFile"])
            provenance = inventory.json(paths["provenanceFile"])
            source_hash = hashlib.sha256(json.dumps(source_map, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
            require(descriptor["sourceIdentity"] == provenance["sourceIdentity"]
                    == "15fe7d5011+followup-source-map-sha256-" + source_hash
                    and provenance["name"] == name and provenance["replacedIndex"] == 1
                    and provenance["unchangedOtherEntries"] == 126
                    and provenance["originalSourceMapSha256"] == ORIGINAL_SOURCE_MAP,
                    "Candidate source provenance differs from the exact measured baseline")
            production_delta = provenance["sourceRoleDeltaVersusMeasured"]["production"]
            require(not production_delta["added"] and not production_delta["removed"], "Unexpected production source shape")
            source_root = snapshot_root + "/modified-sources"
            copied = inventory.tree(source_root)
            require(set(copied) == set(production_delta["changed"]), "Modified source snapshot is incomplete")
            for path, record in copied.items():
                require(record["sha256"] == source_map[path], f"Modified source snapshot differs: {path}")
            for record in provenance["validationRecords"]:
                inventory.add(recorded_relative(record["path"], original_repo), record["sha256"])
                inventory.add(recorded_relative(record["testedSourceFile"], original_repo), record["testedSourceSha256"])
        runtimes[name] = {"sourceIdentity": descriptor["sourceIdentity"], "descriptor": descriptor,
                          "descriptorPaths": paths, "originalManifest": manifest, "entries": entries}
    require(runtimes["candidate1"]["entries"][1]["sha256"] != runtimes["candidate1-and-2"]["entries"][1]["sha256"],
            "Both candidate production trees are identical")
    return {"protocol": protocol, "protocolSha256": sha_bytes(protocol_bytes),
            "runtimes": runtimes, "artifacts": [artifacts[path] for path in sorted(artifacts)]}


def verify_profile_disclosure(inventory: Inventory) -> dict:
    """Verify sanitized recording receipts; never read/package the private raw JFRs."""
    audit = inventory.json(DISCLOSURE_RECEIPT)
    require(audit["format"] == 1 and audit["status"] == "passed" and audit["safeToPackage"] is True,
            "Sanitized JFR disclosure verification is absent, incomplete, or failed")
    records = {item["mode"]: item for item in audit["recordings"]}
    require(len(audit["recordings"]) == 2 and set(records) == {"off", "dense"},
            "Disclosure verification must cover both diagnostic recordings exactly once")
    for field, expected_path in (("auditorSource", FOLLOWUP + "/JfrDisclosureAudit.java"),
                                 ("runnerSource", FOLLOWUP + "/sanitize-jfr-delivery.py")):
        reference = audit[field]
        require(reference["path"] == expected_path, f"Unexpected disclosure source reference: {field}")
        inventory.add(portable(reference["path"]), reference["sha256"])
    summary = inventory.json(FOLLOWUP + "/profile-summary.json", audit["originalProfileSummarySha256"])
    for mode, record in records.items():
        original = record["original"]
        sanitized = record["sanitized"]
        require(original == summary["profileFiles"][mode]
                and original["path"] == FOLLOWUP + "/frozen-" + mode + "/profile.jfr",
                "Original recording provenance differs from the preserved diagnostic receipt")
        relative = FOLLOWUP + "/delivery-profiles/frozen-" + mode + "/profile.jfr"
        require(sanitized["path"] == relative and sanitized["sha256"] != original["sha256"],
                "Sanitized recording is not a separately identified delivery copy")
        observed = inventory.add(relative, sanitized["sha256"])
        require(observed["size"] == sanitized["bytes"], "Sanitized recording size differs")
        with path_under(inventory.repo, relative).open("rb") as stream:
            require(stream.read(4) == b"FLR\0", "Sanitized file does not have a JFR header")
        disclosure_prefix = FOLLOWUP + "/delivery-profiles/frozen-" + mode + "/"
        for field, filename in (("redactedAudit", "redacted-audit.json"), ("commands", "commands.json")):
            reference = record[field]
            require(reference["path"] == disclosure_prefix + filename,
                    f"Unexpected disclosure receipt reference: {mode}/{field}")
            inventory.add(portable(reference["path"]), reference["sha256"])
        redacted = inventory.json(record["redactedAudit"]["path"])
        require(record["redactedAudit"]["valuesEmitted"] is False
                and record["redactedAudit"]["valueDigestsEmitted"] is False
                and redacted["status"] == "passed" and redacted["valuesEmitted"] is False
                and redacted["valueDigestsEmitted"] is False
                and redacted["retainedEventsEquivalent"] is True
                and redacted["excludedDisclosureEventsAbsent"] is True
                and redacted["detectedSecretByteSearchPassed"] is True
                and redacted["retainedPayloadDigestAlgorithm"] == record["retainedPayloadDigestAlgorithm"]
                and redacted["originalRetainedPayloadSha256"] == record["originalRetainedPayloadSha256"]
                and redacted["sanitizedRetainedPayloadSha256"] == record["sanitizedRetainedPayloadSha256"],
                "Referenced redacted audit does not substantiate the receipt")
        counts = inventory.json(FOLLOWUP + "/frozen-" + mode + "/event-counts.json")
        require(redacted["originalEventCounts"] == counts
                and redacted["sanitizedEventCounts"] == record["retainedEventCounts"]
                and redacted["removedEventCounts"] == record["removedEventCounts"],
                "Referenced event-count evidence differs from the receipt")
        expected_removed = {name: counts.get(name, 0) for name in
                            ("jdk.InitialEnvironmentVariable", "jdk.InitialSystemProperty",
                             "jdk.SystemProcess", "jdk.InitialSecurityProperty")}
        require(record["removedEventCounts"] == expected_removed
                and record["retainedEventsEquivalent"] is True
                and record["retainedPayloadDigestAlgorithm"]
                and len(record["originalRetainedPayloadSha256"]) == 64
                and record["originalRetainedPayloadSha256"] == record["sanitizedRetainedPayloadSha256"]
                and record["detectedSecretByteSearchPassed"] is True and record["safeToPackage"] is True,
                "Sanitized recording has not passed removal, retained-event and disclosure checks")
    require(not set(ORIGINAL_PROFILES).intersection(inventory.files), "Private original JFR was selected for delivery")
    return inventory.files[DISCLOSURE_RECEIPT]


def publish_no_replace(source: Path, destination: Path) -> None:
    require(sys.platform.startswith("linux"), "Atomic publication requires Linux renameat2")
    libc = ctypes.CDLL(None, use_errno=True)
    rename = getattr(libc, "renameat2", None)
    require(rename is not None, "renameat2 unavailable; output remains unpublished")
    rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    rename.restype = ctypes.c_int
    if rename(-100, os.fsencode(source), -100, os.fsencode(destination), 1):
        error = ctypes.get_errno()
        if error in (errno.EEXIST, errno.ENOTEMPTY):
            raise FileExistsError(f"Refusing to replace output: {destination}")
        raise OSError(error, os.strerror(error), str(destination))
